PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://example.com/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?point ?pointClass ?ts WHERE {
  ?point a brick:ElectricPower .
  ?point brick:hasPoint ?p .
  ?p rdfs:label ?label .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?cls (COUNT(?s) AS ?n) WHERE {
  ?s a ?cls .
} GROUP BY ?cls ORDER BY ?n

